-- Starter Chordbook for Alimonus (generated by scripts/generate-seed-sql.ts).
-- Public-domain songs and Alimonus originals include full sheets; popular songs are metadata only.
-- Playlists, song states and roadmap items need real user ids, so `npm run provision -- --seed` adds those.
insert into public.songs (id, title, artist, album, alt_titles, duration_ms, release_year, genre, key, bpm, description, credits, chord_sheet, progression, chord_source, provenance)
values
  ('seed-amazing-grace', 'Amazing Grace', 'Traditional (John Newton)', 'Public domain hymn', array[]::text[], 200000, 1779, 'Folk / Hymn', 'G', 80, 'A 3/4 classic and a great first song for practising chord changes on the beat.', 'Words: John Newton (1779). Melody: "New Britain" (1829).', '{title: Amazing Grace}
{key: G}
{tempo: 80}
{time: 3/4}
{c: Intro}
[G] [C] [G] [D]

{start_of_verse: Verse 1}
A[G]mazing grace, how [G7]sweet the [C]sound
That [G]saved a wretch like [D]me
I [G]once was lost, but [G7]now am [C]found
Was [G]blind, but [D7]now I [G]see
{end_of_verse}

{start_of_verse: Verse 2}
''Twas [G]grace that taught my [G7]heart to [C]fear
And [G]grace my fears re[D]lieved
How [G]precious did that [G7]grace ap[C]pear
The [G]hour I [D7]first be[G]lieved
{end_of_verse}

{start_of_verse: Verse 3}
Through [G]many dangers, [G7]toils and [C]snares
I [G]have already [D]come
''Tis [G]grace hath brought me [G7]safe thus [C]far
And [G]grace will [D7]lead me [G]home
{end_of_verse}

{c: Outro}
[C] [G] [D7] [G]', null, 'verified', 'Public-domain lyrics; Alimonus arrangement'),
  ('seed-scarborough-fair', 'Scarborough Fair', 'Traditional', 'English folk ballad', array[]::text[], 190000, null, 'Folk', 'Am', 100, 'Dorian-flavoured ballad: watch the D major in a minor key — that raised 6th is the magic.', 'Traditional English ballad. Lyrics public domain.', '{title: Scarborough Fair}
{key: Am}
{time: 3/4}
{start_of_verse: Verse 1}
[Am]Are you going to [G]Scarborough [Am]Fair?
[C]Parsley, [Am]sage, [C]rose[D]mary and [Am]thyme
Re[Am]member [C]me to one who [G]lives [Am]there
[Am]She once [G]was a true love of [Am]mine
{end_of_verse}

{start_of_verse: Verse 2}
[Am]Tell her to make me a [G]cambric [Am]shirt
[C]Parsley, [Am]sage, [C]rose[D]mary and [Am]thyme
With[Am]out no [C]seams nor [G]needle[Am]work
[Am]Then she''ll [G]be a true love of [Am]mine
{end_of_verse}', null, 'verified', 'Public-domain lyrics; Alimonus arrangement'),
  ('seed-greensleeves', 'Greensleeves', 'Traditional', null, array[]::text[], 180000, null, 'Folk / Renaissance', 'Am', 90, 'Renaissance tune in 6/8. Great for practising E major inside A minor (harmonic minor).', 'Traditional English tune, 16th century.', '{title: Greensleeves}
{key: Am}
{time: 6/8}
{start_of_verse: Verse}
A[Am]las, my love, you [G]do me wrong
To [Am]cast me off dis[E]courteously
For [Am]I have loved [G]you well and long
De[Am]lighting [E]in your [Am]company
{end_of_verse}

{start_of_chorus: Chorus}
[C]Greensleeves was [G]all my joy
And [Am]Greensleeves was my [E]delight
[C]Greensleeves was my [G]heart of gold
And [Am]who but my [E]lady [Am]Greensleeves
{end_of_chorus}', null, 'verified', 'Public-domain lyrics; Alimonus arrangement'),
  ('seed-danny-boy', 'Danny Boy', 'Frederic Weatherly', 'Londonderry Air', array[]::text[], 240000, 1913, 'Folk / Ballad', 'C', 70, 'A slow ballad with secondary dominants (A7, D7). Lovely on piano.', 'Words: Frederic Weatherly (1913). Melody: Londonderry Air (traditional).', '{title: Danny Boy}
{key: C}
{start_of_verse: Verse 1}
Oh [C]Danny boy, the [C7]pipes, the pipes are [F]calling
From [C]glen to glen, and [Am]down the mountain [D7]side [G7]
The [C]summer''s gone, and [C7]all the roses [F]falling
''Tis [C]you, ''tis you must [G7]go and I must [C]bide
{end_of_verse}

{start_of_chorus: Chorus}
But come ye [G7]back when summer''s [C]in the [F]meadow
Or [C]when the valley''s [Am]hushed and white with [D7]snow [G7]
''Tis [C]I''ll be here in [C7]sunshine or in [F]shadow
Oh [C]Danny boy, oh [Am]Danny [Dm]boy, I [G7]love you [C]so
{end_of_chorus}', null, 'verified', 'Public-domain lyrics; Alimonus arrangement'),
  ('seed-portal-lullaby', 'Portal Lullaby', 'Raiyan Kabir', 'Alimonus Originals', array[]::text[], 214000, 2026, 'Psychedelic / Dream pop', 'Em', 84, 'An Alimonus original. Em → Cmaj7 with an open B string droning through the whole thing — let it ring.', 'Written for Alimonus.', '{title: Portal Lullaby}
{key: Em}
{tempo: 84}
{c: Intro}
[Em] [Cmaj7] [Em] [Cmaj7]

{start_of_verse: Verse 1}
[Em]Green light humming in the [Cmaj7]garage at night
[Em]Solder on my fingers and a [Cmaj7]sky gone white
[Am7]Every equation folds [Em]into a door
[Am7]I don''t know which version of [B7]me this is for
{end_of_verse}

{start_of_chorus: Chorus}
So [G]close your eyes, the [D]walls are thin
The [Em]universe is [Cmaj7]leaking in
[G]Count the stars, then [D]count again
We [Am7]left a light on [B7]somewhere in the [Em]end
{end_of_chorus}

{start_of_bridge: Bridge}
[Cmaj7]Ones and zeroes [D]falling like rain
[Bm7]Every loop comes [Em]back around again
{end_of_bridge}', null, 'user', 'Alimonus original'),
  ('seed-night-shift-cat', 'Night Shift Cat', 'Afra Anani', 'Alimonus Originals', array[]::text[], 198000, 2026, 'Pop / Funk', 'Dm', 112, 'An Alimonus original. A minor-key funk strut — mute the strings between hits and keep the 16ths tight.', 'Written for Alimonus.', '{title: Night Shift Cat}
{key: Dm}
{tempo: 112}
{c: Intro}
[Dm7] [G7] [Dm7] [G7]

{start_of_verse: Verse 1}
[Dm7]Twelve o''clock, the [G7]stage lights hum
[Dm7]Something''s tapping [G7]like a drum
[Bbmaj7]Velvet paws on the [A7]checkered floor
[Dm7]She''s been here a [G7]thousand nights before
{end_of_verse}

{c: Pre-Chorus}
[Gm7]Red light blinking, [A7]camera two
[Gm7]Don''t look now, she''s [A7sus4]watching [A7]you

{start_of_chorus: Chorus}
Night shift [Dm]cat, night shift [Bb]cat
[F]Moonwalking out where the [C]shadows are at
Night shift [Dm]cat, gonna [Bb]bring it back
[Gm7]Six a.m. and she [A7]never looks [Dm]back
{end_of_chorus}', null, 'user', 'Alimonus original'),
  ('seed-wiring-the-moon', 'Wiring the Moon', 'Raiyan Kabir & Afra Anani', 'Alimonus Originals', array[]::text[], 226000, 2026, 'Indie / Duet', 'A', 92, 'An Alimonus duet: Raiyan takes verse 1, Afra takes verse 2, both on the chorus. Try capo 2 with G shapes.', 'Written for Alimonus.', '{title: Wiring the Moon}
{key: A}
{tempo: 92}
